-- Finance profitability drill-down: reuses existing orders, order_items, expenses, purchase_orders and supplier_invoices.
-- No new product master, order master or synchronization layer.

CREATE OR REPLACE VIEW public.v_financial_order_item_profitability AS
WITH order_base AS (SELECT o.id order_id,o.order_number,o.created_at,o.store_id,o.customer_name,o.user_id customer_id,COALESCE(NULLIF(o.total_amount,0),NULLIF(o.total_revenue,0),o.total,0) order_revenue,COALESCE(NULLIF(o.product_cost_net,0),NULLIF(o.order_cost,0),0) order_cogs,COALESCE(o.packing_cost_net,o.packing_cost,0)+COALESCE(o.shipping_cost_net,o.shipping_cost,0)+COALESCE(o.gateway_fee_net,o.gateway_fee_actual,o.payment_fee,0) order_variable_cost FROM public.orders o WHERE COALESCE(o.is_deleted,false)=false AND COALESCE(o.payment_status,'')='paid' AND COALESCE(o.order_status,'') NOT IN ('cancelled','refunded')),item_base AS (SELECT ob.*,oi.id order_item_id,oi.product_id,oi.product_name,oi.quantity,COALESCE(oi.total_price,0) item_revenue,COALESCE(oi.quantity,0)*COALESCE(oi.cost_price,0) item_cogs,SUM(COALESCE(oi.total_price,0)) OVER(PARTITION BY oi.order_id) order_item_revenue FROM order_base ob JOIN public.order_items oi ON oi.order_id=ob.order_id),day_keys AS (SELECT created_at::date business_date,store_id FROM order_base GROUP BY created_at::date,store_id),daily_expense AS (SELECT k.business_date,k.store_id,COALESCE((SELECT SUM(CASE WHEN COALESCE(e.is_variable_cost,false) THEN COALESCE(e.amount_net,e.amount_gross,0) ELSE 0 END) FROM public.expenses e WHERE e.invoice_date::date=k.business_date AND e.store_id IS NOT DISTINCT FROM k.store_id AND COALESCE(e.pricing_relevant,true)=true),0) variable_expense,COALESCE((SELECT SUM(CASE WHEN NOT COALESCE(e.is_variable_cost,false) AND COALESCE(e.expense_type,'operating')='operating' THEN COALESCE(e.amount_net,e.amount_gross,0) ELSE 0 END) FROM public.expenses e WHERE e.invoice_date::date=k.business_date AND e.store_id IS NOT DISTINCT FROM k.store_id AND COALESCE(e.pricing_relevant,true)=true),0) operating_expense,COALESCE((SELECT SUM(ob.order_revenue) FROM order_base ob WHERE ob.created_at::date=k.business_date AND ob.store_id IS NOT DISTINCT FROM k.store_id),0) day_revenue FROM day_keys k) SELECT ib.order_id,ib.order_number,ib.created_at,ib.store_id,ib.customer_id,ib.customer_name,ib.order_item_id,ib.product_id,ib.product_name,ib.quantity,ib.item_revenue,ib.item_cogs,CASE WHEN ib.order_item_revenue>0 THEN ib.order_variable_cost*(ib.item_revenue/ib.order_item_revenue) ELSE 0 END allocated_order_variable_cost,ib.item_revenue-ib.item_cogs-CASE WHEN ib.order_item_revenue>0 THEN ib.order_variable_cost*(ib.item_revenue/ib.order_item_revenue) ELSE 0 END contribution_profit,CASE WHEN de.day_revenue>0 THEN ib.item_revenue/de.day_revenue*de.operating_expense ELSE 0 END allocated_operating_expense,ib.item_revenue-ib.item_cogs-CASE WHEN ib.order_item_revenue>0 THEN ib.order_variable_cost*(ib.item_revenue/ib.order_item_revenue) ELSE 0 END-CASE WHEN de.day_revenue>0 THEN ib.item_revenue/de.day_revenue*de.operating_expense ELSE 0 END allocated_net_profit FROM item_base ib JOIN daily_expense de ON de.business_date=ib.created_at::date AND de.store_id IS NOT DISTINCT FROM ib.store_id;
CREATE OR REPLACE VIEW public.v_financial_monthly_pnl AS SELECT date_trunc('month',business_date)::date AS period_month,COALESCE(SUM(orders),0)::bigint orders,COALESCE(SUM(units_sold),0)::bigint units_sold,COALESCE(SUM(revenue),0) revenue,COALESCE(SUM(cogs),0) cogs,COALESCE(SUM(variable_costs),0) variable_costs,COALESCE(SUM(operating_expenses),0) operating_expenses,COALESCE(SUM(finance_costs),0) finance_costs,COALESCE(SUM(taxes),0) taxes,COALESCE(SUM(gross_profit),0) gross_profit,COALESCE(SUM(contribution_profit),0) contribution_profit,COALESCE(SUM(net_profit),0) net_profit FROM public.v_financial_daily_pnl GROUP BY date_trunc('month',business_date)::date;
CREATE OR REPLACE FUNCTION public.get_finance_product_profitability(p_start_date date,p_end_date date,p_store_id uuid DEFAULT NULL) RETURNS TABLE(product_id uuid,product_name text,orders bigint,units_sold bigint,revenue numeric,cogs numeric,variable_costs numeric,contribution_profit numeric,allocated_operating_expense numeric,allocated_net_profit numeric,margin_pct numeric) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT product_id,MAX(product_name),COUNT(DISTINCT order_id),COALESCE(SUM(quantity),0)::bigint,COALESCE(SUM(item_revenue),0),COALESCE(SUM(item_cogs),0),COALESCE(SUM(allocated_order_variable_cost),0),COALESCE(SUM(contribution_profit),0),COALESCE(SUM(allocated_operating_expense),0),COALESCE(SUM(allocated_net_profit),0),CASE WHEN SUM(item_revenue)<>0 THEN ROUND(SUM(contribution_profit)/SUM(item_revenue)*100,2) ELSE 0 END FROM public.v_financial_order_item_profitability WHERE created_at::date BETWEEN p_start_date AND p_end_date AND (p_store_id IS NULL OR store_id=p_store_id) GROUP BY product_id ORDER BY SUM(item_revenue) DESC; $$;
CREATE OR REPLACE FUNCTION public.get_finance_customer_profitability(p_start_date date,p_end_date date,p_store_id uuid DEFAULT NULL) RETURNS TABLE(customer_key text,customer_name text,orders bigint,units_sold bigint,revenue numeric,cogs numeric,variable_costs numeric,contribution_profit numeric,allocated_operating_expense numeric,allocated_net_profit numeric,margin_pct numeric) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT COALESCE(customer_id::text,NULLIF(customer_name,''),'guest'),MAX(customer_name),COUNT(DISTINCT order_id),COALESCE(SUM(quantity),0)::bigint,COALESCE(SUM(item_revenue),0),COALESCE(SUM(item_cogs),0),COALESCE(SUM(allocated_order_variable_cost),0),COALESCE(SUM(contribution_profit),0),COALESCE(SUM(allocated_operating_expense),0),COALESCE(SUM(allocated_net_profit),0),CASE WHEN SUM(item_revenue)<>0 THEN ROUND(SUM(contribution_profit)/SUM(item_revenue)*100,2) ELSE 0 END FROM public.v_financial_order_item_profitability WHERE created_at::date BETWEEN p_start_date AND p_end_date AND (p_store_id IS NULL OR store_id=p_store_id) GROUP BY customer_id,customer_name ORDER BY SUM(item_revenue) DESC; $$;
CREATE OR REPLACE FUNCTION public.get_finance_supplier_performance(p_start_date date,p_end_date date) RETURNS TABLE(supplier_id uuid,supplier_name text,purchase_orders bigint,units_purchased bigint,purchase_value numeric,invoices bigint,invoiced_value numeric,outstanding_value numeric) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ WITH po AS (SELECT p.supplier_id,COUNT(DISTINCT p.id) purchase_orders,COALESCE(SUM(i.quantity_ordered),0)::bigint units_purchased,COALESCE(SUM(i.quantity_ordered*COALESCE(i.unit_cost_ex_vat,i.unit_cost,0)),0) purchase_value FROM public.purchase_orders p LEFT JOIN public.purchase_order_items i ON i.purchase_order_id=p.id WHERE p.order_date BETWEEN p_start_date AND p_end_date GROUP BY p.supplier_id),inv AS (SELECT s.supplier_id,COUNT(*) invoices,COALESCE(SUM(s.total_amount),0) invoiced_value,COALESCE(SUM(GREATEST(COALESCE(s.total_amount,0)-COALESCE(s.amount_paid,0),0)),0) outstanding_value FROM public.supplier_invoices s WHERE s.invoice_date BETWEEN p_start_date AND p_end_date GROUP BY s.supplier_id) SELECT sp.id,sp.name,COALESCE(po.purchase_orders,0),COALESCE(po.units_purchased,0),COALESCE(po.purchase_value,0),COALESCE(inv.invoices,0),COALESCE(inv.invoiced_value,0),COALESCE(inv.outstanding_value,0) FROM public.suppliers sp LEFT JOIN po ON po.supplier_id=sp.id LEFT JOIN inv ON inv.supplier_id=sp.id WHERE COALESCE(sp.is_active,true)=true ORDER BY COALESCE(po.purchase_value,0) DESC,sp.name; $$;
